        print(f"Color {color}: bbox {top},{left} to {bot},{right}, interior {int_h}x{int_w}")

        patterns = {
            (5, 3): [(0,1), (1,0), (1,1), (2,1), (2,2), (3,0), (3,1), (3,2)],
            (4, 3): [(1,2), (2,1), (2,2), (3,2), (3,3), (4,1)],
        }

        if (int_h, int_w) in patterns:
            pattern = patterns[(int_h, int_w)]
            print(f"  Using pattern: {pattern}")

